export const SOURCES: CourseSource[] = [
  { id: 'stoic-epictetus-iep', title: 'Keith H. Seddon · Epictetus (Internet Encyclopedia of Philosophy)', url: 'https://iep.utm.edu/epictetu/', type: 'guidance', finding: 'Epicteto (c. 55–135 d. C.) nació esclavo en Hierápolis, fue liberado más tarde y enseñó filosofía en Nicópolis, Grecia; su alumno Arriano recogió sus enseñanzas en los Discursos y en el Manual. El artículo explica su distinción central entre lo que depende de nosotros (nuestras opiniones, intenciones, deseos, aversiones y el uso que hacemos de las impresiones) y lo que no (el cuerpo, las posesiones, la reputación, la salud, el estatus y los resultados de nuestras acciones), y su enseñanza de que a las personas las perturban sus juicios sobre los hechos y no los hechos en sí.', limitation: 'Es un panorama enciclopédico de la filosofía, no investigación psicológica; no trata la terapia moderna. La página fue leída; los textos antiguos se parafrasean en este curso, no se citan.' },
  { id: 'stoic-seneca-iep', title: 'Robert Wagoner · Seneca (Internet Encyclopedia of Philosophy)', url: 'https://iep.utm.edu/seneca/', type: 'guidance', finding: 'Séneca (c. 4 a. C.–65 d. C.) fue un filósofo estoico que fue tutor del joven Nerón y más tarde uno de sus consejeros. El artículo explica la visión estoica, tal como la presenta Séneca, de que emociones como la ira implican juicios de valor: el primer movimiento ante una situación es involuntario, pero enojarse requiere dar por buena la idea de que te han agraviado.', limitation: 'Es un panorama enciclopédico, no investigación. No describe el repaso nocturno de Séneca ni su consejo de anticipar la adversidad; en este curso esas prácticas se apoyan en el manual de la Semana Estoica. La página fue leída.' },
  { id: 'stoic-week-handbook', title: 'Stoicism Today (Gill, Ussher, Sellars, LeBon, Evans, Garratt, Robertson) · Stoic Week 2016 Handbook (Modern Stoicism)', url: 'https://modernstoicism.com/wp-content/uploads/2016/10/Stoic-Week-2016-Handbook-Stoicism-Today.pdf', type: 'technique', finding: 'El manual enseña ejercicios estoicos diarios junto con sus fuentes antiguas: la dicotomía del control del Manual de Epicteto (preguntarse ante cada situación si depende de ti); una meditación matutina que ensaya las dificultades probables del día y planea buenas respuestas; la premeditación de la adversidad hecha de forma realista, con una intensidad manejable y sin rumiar; un repaso nocturno de cinco a diez minutos basado en Séneca y Epicteto (qué hice mal, qué hice bien, qué podría hacer de otra manera, revisado como lo haría un amigo y no con dureza); y la visión desde lo alto de Marco Aurelio. Rechaza la idea de que el estoicismo signifique reprimir las emociones y describe la psicología estoica como una influencia en la terapia cognitivo-conductual moderna.', limitation: 'Es una guía de práctica escrita por filósofos, especialistas en clásicos y terapeutas, no un ensayo. Indica que no sustituye el consejo ni el tratamiento médicos y que el curso no es adecuado para personas con problemas graves de salud mental, como depresión clínica o TEPT. El PDF fue leído.' },
  { id: 'stoic-week-report', title: 'Tim LeBon · Report on Stoic Week 2021 (Modern Stoicism)', url: 'https://modernstoicism.com/wp-content/uploads/2022/01/Stoic-Week-2021-Results-Tim-LeBon-1-1.pdf', type: 'research', finding: '1,369 personas completaron cuestionarios válidos al inicio del curso en línea gratuito de siete días y 459 al final (una tasa de finalización del 33%); los participantes dedicaron en promedio 42 minutos al día. Entre quienes lo terminaron, el florecimiento subió un 11.5%, la satisfacción con la vida un 14.5% y las emociones positivas un 13%, mientras que las emociones negativas bajaron un 21%.', limitation: 'Es un informe de los organizadores del curso. Los participantes eligieron tomar parte, no hubo grupo de control, todas las medidas fueron autoinformadas y dos tercios de quienes empezaron no completaron el cuestionario final, así que no puede demostrar que la práctica estoica causara los cambios. El PDF fue leído.' },
  { id: 'stoic-kross-distancing', title: 'Kross & Ayduk · 2017 · Self-distancing: theory, research, and current directions (Advances in Experimental Social Psychology, vol. 55)', url: 'https://sites.lsa.umich.edu/emotion-selfcontrol-psych/wp-content/uploads/sites/1322/2017/09/Self-distancing-theory-research-future.pdf', type: 'research', finding: 'La revisión resume experimentos que comparan la reflexión inmersa en uno mismo (revivir un hecho con tus propios ojos) con la reflexión distanciada (verte desde lejos, como una mosca en la pared). El distanciamiento redujo la emoción negativa y la rumiación, desplazó el pensamiento de recontar detalles a darle sentido al hecho, aceleró la recuperación de la presión arterial, redujo las respuestas agresivas y favoreció un razonamiento más sabio; sus beneficios se mantuvieron en el tiempo mejor que los de la distracción. Imaginar cómo te sentirás dentro de diez años redujo el malestar, al parecer porque resalta que los sentimientos pasan. Usar tu propio nombre o “tú” en el diálogo interno produjo beneficios similares. Los autores rastrean la idea en parte hasta el concepto de distanciamiento de Aaron Beck en la terapia cognitiva.', limitation: 'Son sobre todo estudios breves de laboratorio, a menudo con estudiantes. Los beneficios fueron más claros en las personas con más malestar y pequeños o ausentes en algunas muestras con poco malestar; los autores distinguen entre distanciarse para comprender los sentimientos y distanciarse para evitarlos. El PDF del capítulo fue leído.' },
  { id: 'stoic-kross-self-talk', title: 'Kross et al. · 2014 · Self-talk as a regulatory mechanism: how you do it matters (Journal of Personality and Social Psychology)', url: 'https://doi.org/10.1037/a0035173', type: 'research', finding: 'Siete estudios con 585 participantes: reflexionar sobre uno mismo con pronombres que no están en primera persona y con el propio nombre, en lugar de “yo”, aumentó el autodistanciamiento. En tareas de primera impresión y de hablar en público, este grupo rindió mejor, sintió menos malestar y rumió menos después, y valoró los estresores futuros más como desafíos que como amenazas. Un metaanálisis de los estudios halló que los beneficios no dependían de la ansiedad social.', limitation: 'Tareas breves de laboratorio; no se evaluaron los efectos a largo plazo ni los clínicos. Solo se leyó el resumen (a través de Europe PMC).' },
];

